class Base58Encoder:
    '''This class encodes numbers using the Base58 algorithm'''
    def __init__(self,number):
        self.number = number

    def encode(self):
        encoded = "" 
        alphabet = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz"

        while self.number > 0:
            remainder = self.number % 58 
            self.number = self.number // 58 
            encoded = alphabet[remainder] + encoded 

        return encoded

def subset(arr, K): 
    n = len(arr) 
    subset_arr = [0]; 

    for i in range (0, n): 
        x = len(subset_arr) 
        for j in range(0, x): 

            # Generate subset by adding 
            # elements of A
            temp = [] 
            temp = subset_arr[j] 
            temp.append(arr[i]) 

            # Append in the list 
            subset_arr.append(temp) 

    # Return K size subset 
    length = len(subset_arr) 
    if (length >= K): 
        return subset_arr[length - K:] 
    else: 
        return -1

