class Node: 

    def __init__(self, data): 
        self.data = data  
        self.next = None

def remove_duplicates(head): 
    h = {} 

    temp = head 
    prev = None
    while(temp): 
        if temp.data in h: 
            prev.next = temp.next
            temp = None
        else: 
            h[temp.data] = True
            prev = temp 
        temp = prev.next

