def filter_by(lst, criteria):
    """This function takes an array of elements and a criteria and returns an array of elements filtered by the criteria."""
    return [x for x in lst if criteria(x)]

def most_frequent_char(s):
    counts = {}
    max_char = ""
    max_count = 0
    for c in s:
        if c in counts:
            counts[c] += 1
        else:
            counts[c] = 1
        if counts[c] > max_count:
            max_char = c
            max_count = counts[c]
    return max_char

# example
s = "Hello world!"
print(most_frequent_char(s))

def parse_string(string):
    words = string.split()
